import sqlite3
conn = sqlite3.connect('db/cards.db')
cur = conn.cursor()
content = open('doc/legalities.md').read()
parts = content.split('\n\n')

data = {}
for i, p in enumerate(parts):
    id_match = re.search(r'ID\s+(\d+)', p)
    cardsid_match = re.search(r'cards_id\s+(\d+)', p)
    if id_match and cardsid_match:
        cardsid = cardsid_match.group(1)
        if re.search(r'Commander', p, re.I):
            status = re.search(r'status is (\w+)', p, re.I)
            fmt = re.search(r'format', p, re.I)
            if status or fmt:
                data[cardsid] = {'id': id_match.group(1), 'status': status.group(1) if status else None, 'text': p[:500]}

card_ids = list(data.keys())
print(f'Found {len(card_ids)} cards with Commander in text')
print('Sample:', list(data.items())[:5])

